target=[[1,3,3],[1,2,2],[1,3,2]]
def f(grid):
    h=len(grid);w=len(grid[0]);seen=[[False]*w for _ in range(h)];shapes=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                st=[(i,j)];comp=[];seen[i][j]=True
                while st:
                    y,x=st.pop();comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and grid[ny][nx] and not seen[ny][nx]:
                                seen[ny][nx]=True;st.append((ny,nx))
                ys=[p[0] for p in comp];xs=[p[1] for p in comp]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                sub=[[grid[y][x] for x in range(x0,x1+1)] for y in range(y0,y1+1)]
                shapes.append(sub)
    best=max(shapes,key=lambda s:len({c for r in s for c in r}))
    return best
